BeforeAll {
    . (Join-Path -Path $PSScriptRoot -ChildPath 'TestSupport.ps1')
    if (-not $env:FILESCOM_MOCK_URL) {
        throw 'FILESCOM_MOCK_URL must name a running Files.com mock server.'
    }
    $connection = Connect-FilesAccount -ApiKey (ConvertTo-SecureString -String 'mock-api-key' -AsPlainText -Force) -BaseUrl $env:FILESCOM_MOCK_URL -MaxNetworkRetries 0 -NoDefault
}

AfterAll {
    Disconnect-FilesAccount -Connection $connection -Confirm:$false
}

Describe 'Operations against the Files.com mock server' {
    It '<Operation> through <Command>' -TestCases $script:Operations {
        if ($ExampleDefect) {
            # The mock answers with the schema's inconsistent example (contract_example_defect), which the SDK must refuse.
            { & $Invocation } | Should -Throw -ErrorId 'Files.InvalidResponse*' -Because $ExampleDefect
            return
        }
        $result = & $Invocation

        if ($Writes) {
            $result | Should -Not -BeNullOrEmpty
            $result | ForEach-Object { $_ | Should -BeOfType ([FilesCom.PowerShell.FilesObject]) }
        }
        else {
            $result | Should -BeNullOrEmpty
        }
    }
}
